import fcntl,hashlib,json,pathlib,shutil
def capture(source,target):
    source=pathlib.Path(source);target=pathlib.Path(target)
    if target.exists():raise FileExistsError(target)
    with (source/'writer.lock').open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_SH)
        raw=(source/'data.json').read_bytes();index=json.loads((source/'index.json').read_bytes());data=json.loads(raw)
        if index['generation']!=data['generation'] or index['data_sha256']!=hashlib.sha256(raw).hexdigest():
            raise ValueError('application files are not one consistent generation')
        target.mkdir()
        for name in ('index.json','data.json'):shutil.copy2(source/name,target/name)
        return {'generation':data['generation'],'data_sha256':hashlib.sha256(raw).hexdigest()}
